// Environment art manifest: per-world tilesets and parallax backgrounds, plus
// the shared animated liquids. Generated by tools/art/worlds.mjs. Vite turns
// each import into a content-hashed URL (tiny files are inlined), so world art
// is fetched lazily per world without risking stale caches.

const urls = import.meta.glob<string>(['./tilesets/*.png', './backgrounds/*.png', './liquids/*.png'], { eager: true, import: 'default' });
const url = (p: string): string => {
  const u = urls[p];
  if (!u) throw new Error(`missing environment asset ${p}`);
  return u;
};

export type BgLayer = 'sky' | 'far' | 'mid';
export const BG_LAYERS: readonly BgLayer[] = ['sky', 'far', 'mid'];
export const LIQUIDS = ['lava', 'water', 'toxic'] as const;
export type LiquidName = (typeof LIQUIDS)[number];

export interface WorldArt {
  tiles: string;
  bg: Record<BgLayer, string>;
}

export const WORLD_ART: Record<number, WorldArt> = Object.fromEntries(
  [1, 2, 3, 4].map((w) => [w, {
    tiles: url(`./tilesets/w${w}.png`),
    bg: { sky: url(`./backgrounds/w${w}_sky.png`), far: url(`./backgrounds/w${w}_far.png`), mid: url(`./backgrounds/w${w}_mid.png`) },
  }]),
);

export const LIQUID_ART: Record<LiquidName, string> = {
  lava: url('./liquids/lava.png'), water: url('./liquids/water.png'), toxic: url('./liquids/toxic.png'),
};

/** Texture keys. */
export const tilesKey = (w: number): string => `tiles-w${w}`;
export const bgKey = (w: number, layer: BgLayer): string => `bg-w${w}-${layer}`;
export const liquidKey = (n: LiquidName): string => `liq-${n}`;

/** Tileset layout (8 columns of 32x32 tiles). */
export const TILESET = {
  cols: 8,
  /** 0-15: solid tile by exposed sides, N=1 E=2 S=4 W=8. */
  deep: [16, 17, 18],
  oneWay: [19, 20, 21],
  spikes: 22,
  /** Concave corner overlays: NE, NW, SE, SW. */
  inner: [23, 24, 25, 26],
  decor: [27, 28, 29],
  hanging: [30, 31],
} as const;

/** Liquid sheet layout: four 64x12 surface frames stacked, then two 32x32 basin tiles. */
export const LIQUID_SHEET = { surfaceW: 64, surfaceH: 12, frames: 4, basinY: 48, surfaceOffsetY: -5 } as const;

/** Interactive-object atlas (Phaser JSON hash; generated by tools/art/objects.mjs). */
export { default as OBJECTS_PNG } from './objects/objects.png';
export { default as OBJECTS_JSON } from './objects/objects.json';
